<?php if($settings['flags']['contact']):?><section id="contact" class="contact"><div><p class="eyebrow"><?=me(__('manor.your_next_occasion'))?></p><h2><?=me($settings['contact_title'])?></h2><p><?=me($settings['contact_text'])?></p></div><div class="contact-grid"><form method="post" action="/manor/message"><?=csrf()?><input type="hidden" name="kind" value="contact"><?=field('email',__('manor.your_email'),'','email')?><label><?=me(__('manor.your_message'))?><textarea name="message" required maxlength="5000"></textarea></label><label class="check"><input type="checkbox" name="consent" value="1" required><?=me(__('manor.i_agree_to_the_privacy_notice_below'))?></label><p class="muted"><?=me($settings['privacy'])?></p><label class="honeypot" aria-hidden="true"><?=me(__('manor.leave_blank'))?><input name="website" tabindex="-1" autocomplete="off"></label><button><?=me(__('manor.send_your_message'))?></button></form><?=media($settings,'contact')?></div></section><?php endif?>
